contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 betLimit, uint256 wagerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(betLimit > 0, "betLimit must be positive");
        require(wagerAmount == betLimit, "wagerAmount must equal betLimit");
        require(address(this).balance >= wagerAmount, "insufficient balance");

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(betLimit); if (__ESBMC_reverted()) return;

        uint256 balanceBefore = address(c).balance;
        c.wager{value: wagerAmount}(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(c).balance;

        bool hasWagered = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        assert(balanceAfter == balanceBefore + wagerAmount && hasWagered);
    }

    receive() external payable {}
}

