        try c.hasPlayerWagered(address(this)) returns (bool __r) { hasWagered = __r; } catch { return; }
        assertTrue(balanceAfter == balanceBefore + wagerAmount && hasWagered);
    }

    function testFuzz_run(uint256 betLimit, uint256 wagerAmount) public {
        _run(betLimit, wagerAmount);
    }

